css:
.tpl-hf-logo-chain { position: relative; width: 100%; height: 100%; overflow: hidden; display: flex; flex-direction: column; align-items: center; justify-content: center; background: linear-gradient(125deg, #c9cbff 0%, #8392ff 45%, #8de5cf 100%); font-family: var(--font-sans, 'Inter', 'PingFang SC', sans-serif); color: #0f172a; padding: 0 6%; }
.tpl-hf-logo-chain .aurora-card { position: relative; width: 88%; max-width: 1340px; border-radius: 30px; background: rgba(255,255,255,0.72); border: 1px solid rgba(255,255,255,0.85); backdrop-filter: blur(24px); box-shadow: 0 28px 80px rgba(15,23,42,0.16); padding: clamp(28px, 5vmin, 64px); text-align: center; opacity: 0; }
.tpl-hf-logo-chain .lc-brand { font-size: clamp(22px, 3.2vmin, 40px); font-weight: 800; color: #312e81; letter-spacing: 0.06em; text-transform: uppercase; opacity: 0; }
.tpl-hf-logo-chain .lc-stat-row { margin: clamp(14px, 3vh, 32px) 0; opacity: 0; }
.tpl-hf-logo-chain .lc-metric { font-size: clamp(56px, 11vmin, 136px); font-weight: 900; letter-spacing: -0.04em; line-height: 1; color: #0f172a; font-variant-numeric: tabular-nums; }
.tpl-hf-logo-chain .lc-label { margin-top: 8px; font-size: clamp(16px, 2.3vmin, 26px); font-weight: 600; color: #475569; }
.tpl-hf-logo-chain .pill-chain { display: flex; flex-wrap: wrap; align-items: center; justify-content: center; gap: clamp(10px, 1.8vw, 22px); margin-top: clamp(18px, 3.2vh, 36px); }
.tpl-hf-logo-chain .lc-pill { padding: 0.6em 1.35em; border-radius: 999px; background: #0f172a; color: #f8fafc; font-size: clamp(14px, 1.9vmin, 22px); font-weight: 700; box-shadow: 0 10px 26px rgba(15,23,42,0.2); opacity: 0; }
